// New: per-unit pixel art for the tactical grid. Humans (player and NPCs) are drawn in the armor
// they actually wear - armor_atlas.png holds every faction armor sprite with its faction armband
// baked in - and mutants use mutant_atlas.png (cloaked variants swap in while IsCloaked). Both
// atlases and their cell order (GameData/SpriteAtlasIndex.cs) are generated by
// ArtSource/export_to_unity.py. Sliced at runtime with Sprite.Create, which doesn't need the
// texture to be readable, so the normal PixelSpriteImporter settings are enough.
// Returns null for anything without art; TacticalGridView then keeps its old fallback marker.
using System.Collections.Generic;
using GameData;
using UnityEngine;

namespace GameCore
{
    public static class UnitSprites
    {
        private const int Cell = 16;
        private static Dictionary<string, Sprite> _armor, _mutants, _walkA, _walkB, _back, _backWalkA, _backWalkB;
        // Batch 29: the project enters Play mode without a domain reload, so statics survive between
        // runs while the sprites/textures they point at are destroyed - clear the caches each run.
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetCaches() { _hd = null; _armor = _mutants = _walkA = _walkB = _back = _backWalkA = _backWalkB = null; }

        /// <summary>Batch 128 (Yan: "add the back as well so the player can know which way the npc's are looking"): a unit
        /// whose aim (or gaze) from `from` to `to` goes up the screen shows its back - more than ~17 degrees above level.</summary>
        public static bool Away(Vector3 from, Vector3 to)
        {
            float dx = to.x - from.x, dy = to.y - from.y;
            return dy > 0.3f * Mathf.Sqrt(dx * dx + dy * dy) && dy > 0.001f;
        }

        /// <summary>Batch 128: the back view of a human (armor_back_atlas.png, ArtSource/make_back_atlas.py); null for mutants.</summary>
        public static Sprite Back(ICombatant unit)
        {
            Load();
            var armor = unit is Player p ? p.EquippedArmor : unit is HumanEnemy h ? h.EquippedArmor : null;
            return armor != null && _back.TryGetValue(armor.Name, out var s) ? s : null;
        }


        public static Sprite For(ICombatant unit)
        {
            Load();
            switch (unit)
            {
                case Player p: return ForArmor(p.EquippedArmor);
                case HumanEnemy h: return ForArmor(h.EquippedArmor);
                case Mutant m:
                    string name = m.Db?.Name ?? m.Name;
                    var hd = HD(name);
                    if (hd != null) return hd;                                       // the approved double-resolution art (Batch 130c)
                    if (m.IsCloaked && _mutants.TryGetValue(name + " (cloaked)", out var cloaked)) return cloaked;
                    return _mutants.TryGetValue(name, out var s) ? s : null;
                default: return null;
            }
        }

        // Batch 130c's mutants at double resolution (ArtSource/make_mutants_hd.py -> Sprites/Mutants/mutant_hd_<key>.png): 32 px a
        // tile like the in-hand guns, so a 48x32 hound covers the ground a 24x16 one would; the feet sit on the tile's ground
        // line (16 px under the middle of a tile, where a 16 px human's feet are). They face right; TacticalGridView mirrors them.
        // Mutants without one keep their old atlas cell (Rot Swarm, Alpha Prowler, Mind Weaver, Void Weaver).
        private static Dictionary<string, Sprite> _hd;
        public static Sprite HD(string name)
        {
            if (_hd == null)
            {
                _hd = new Dictionary<string, Sprite>();
                foreach (var n in new[] { "Pallid Prowler", "Blind Maw", "Veil Prowler", "Dread Prowler", "Blight Brute" })
                {
                    var tex = Resources.Load<Texture2D>("Sprites/Mutants/mutant_hd_" + n.ToLowerInvariant().Replace(' ', '_'));
                    if (tex != null) _hd[n] = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 16f / tex.height), 2 * Cell);
                }
            }
            return name != null && _hd.TryGetValue(name, out var s) ? s : null;
        }

        public static Sprite ForArmor(ArmorDef armor)
        {
            Load();
            return armor != null && _armor.TryGetValue(armor.Name, out var s) ? s : null;
        }

        /// <summary>Batch 24: walking frame (0 = left foot up, 1 = right) for humans, null for mutants
        /// or when the walk atlases (ArtSource/make_walk_atlas.py) aren't in the project.</summary>
        public static Sprite Walk(ICombatant unit, int frame, bool away = false)
        {
            Load();
            var armor = unit is Player p ? p.EquippedArmor : unit is HumanEnemy h ? h.EquippedArmor : null;
            var set = away ? (frame == 0 ? _backWalkA : _backWalkB) : frame == 0 ? _walkA : _walkB;
            return armor != null && set.TryGetValue(armor.Name, out var s) ? s : null;
        }

        private static void Load()
        {
            if (_armor != null) return;
            _walkA = Slice("Sprites/armor_walk_a", SpriteAtlasIndex.Armor);
            _walkB = Slice("Sprites/armor_walk_b", SpriteAtlasIndex.Armor);
            _armor = Slice("Sprites/armor_atlas", SpriteAtlasIndex.Armor);
            _back = Slice("Sprites/armor_back_atlas", SpriteAtlasIndex.Armor);
            _backWalkA = Slice("Sprites/armor_back_walk_a", SpriteAtlasIndex.Armor);
            _backWalkB = Slice("Sprites/armor_back_walk_b", SpriteAtlasIndex.Armor);
            _mutants = Slice("Sprites/mutant_atlas", SpriteAtlasIndex.Mutants);
        }

        private static Dictionary<string, Sprite> Slice(string path, string[] order)
        {
            var sprites = new Dictionary<string, Sprite>();
            var tex = Resources.Load<Texture2D>(path);
            if (tex == null) return sprites;
            for (int i = 0; i < order.Length; i++)
            {
                int col = i % SpriteAtlasIndex.Columns, row = i / SpriteAtlasIndex.Columns;
                var rect = new Rect(col * Cell, tex.height - (row + 1) * Cell, Cell, Cell); // atlas row 0 is the top
                sprites[order[i]] = Sprite.Create(tex, rect, new Vector2(0.5f, 0.5f), Cell);
            }
            return sprites;
        }
    }
}
